Ext.define('BNK.view.Budget.bgx.com.BgxItmCpnt51MViewController', {
    extend: 'BaseViewController',
    alias: 'controller.BgxItmCpnt51MViewController',

    config: {
        viewId: 'BgxItmCpnt51M'
    },

    /* 팝업 닫기 */
    onClose: function(button, e, eOpts) {
        this.getView().close();
    },

    /* 매출전표 팝업 */
    onContainerInitialize: function(component, eOpts) {
        var me = this,
            vm = me.getViewModel(),
            refs = me.getReferences(),
            records = component.initialConfig.param;

        for(var key in records){
            if(!records[key] || records[key] === ' '){
                records[key] = '-';
            }
        }

        var rtnData = Ext.clone(records);
        rtnData.cdno = FormatUtils.cardNoFormat(records.cdno, true);
        rtnData.expireDt = '****-**'; /*[요건]*/
        rtnData.apvlDtHr = Ext.String.format("{0} {1}", DateUtils.parseDate(records.apvlDt), records.apvlHr.substr(0,2) + ':' + records.apvlHr.substr(2,2));
        rtnData.apvlAmtDom = FormatUtils.moneyFormat(records.apvlAmtDom);
        rtnData.trnsAmtWc = FormatUtils.moneyFormat(records.trnsAmtWc);
        rtnData.stxat = FormatUtils.moneyFormat(records.stxat);
        rtnData.mcBzno = FormatUtils.bizNoFormat(records.mcBzno);
        rtnData.mcTlno = FormatUtils.phoneNumFormat(records.mcTlno);

        vm.set('records', rtnData);

        this.getView().setAlwaysOnTop(true);

    }

});